                v = q.popleft()
                order.append(v)
                for w in adj[v]:
                    indeg[w] -= 1
                    if indeg[w] == 0:
                        q.append(w)
            return {v: i for i, v in enumerate(order)} if len(order) == k else None

        row, col = topo(rowConditions), topo(colConditions)
        if row is None or col is None:
            return []
        m = [[0] * k for _ in range(k)]
        for v in range(1, k + 1):
            m[row[v]][col[v]] = v
        return m

